/*
 * Dive Computer V2 rev 1 - pin control definitions
 *
 * Final pinout, validated against the KiCad schematic netlist and the
 * nRF52833 QDAA (QFN40) pin assignments (product spec v1.2, Table 140).
 *
 * Only bonded QFN40 GPIOs are used. Per Table 140, P0.02, P0.03, P0.09,
 * P0.10 and P0.28-P0.30 are standard-drive, low-frequency only (<= 10 kHz)
 * pins: they carry the slow control/event signals below. All fast signals
 * (I2C at 400 kHz, screen SPI at 8 MHz) are on full-speed GPIOs.
 *
 * Fast GPIOs : P0.04, P0.05, P0.11, P1.09, P0.15, P0.17, P0.20, P0.31
 * Slow GPIOs : P0.02, P0.03, P0.09, P0.10, P0.28, P0.29, P0.30
 * Reserved   : P0.00/P0.01 (32 kHz crystal XL1/XL2), P0.18 (nRESET)
 *
 * SPDX-License-Identifier: Apache-2.0
 */

&pinctrl {
	/* Shared sensor bus: LIS2MDL (0x1E), LIS2DUX12 (0x19), VEML6035,
	 * TMAG3001 (ADDR=GND), MS5837-30BA (0x76), DRV2624 (0x5A).
	 * External 4.7k pull-ups to the always-on 1.8 V rail. */
	i2c0_default: i2c0_default {
		group1 {
			psels = <NRF_PSEL(TWIM_SCL, 0, 15)>,
				<NRF_PSEL(TWIM_SDA, 0, 17)>;
		};
	};

	i2c0_sleep: i2c0_sleep {
		group1 {
			psels = <NRF_PSEL(TWIM_SCL, 0, 15)>,
				<NRF_PSEL(TWIM_SDA, 0, 17)>;
			/* High-Z in sleep: the external pull-ups to the
			 * always-on 1.8 V rail keep the bus defined while
			 * the sensors stay powered for wake-up events. */
			low-power-enable;
		};
	};

	/* JDI LPM013M091A, 3-wire 9-bit SPI. 9-bit frames are produced by
	 * packing 8 frames into 9 bytes and issuing one transfer per line
	 * with CS held low (nRF SPIM is 8-bit only). tSCYCW min = 16 ns for
	 * GRAM writes, so 8 MHz is within spec. */
	spi1_default: spi1_default {
		group1 {
			psels = <NRF_PSEL(SPIM_SCK, 0, 4)>,
				<NRF_PSEL(SPIM_MOSI, 0, 5)>;
		};
	};

	spi1_sleep: spi1_sleep {
		group1 {
			psels = <NRF_PSEL(SPIM_SCK, 0, 4)>,
				<NRF_PSEL(SPIM_MOSI, 0, 5)>;
			/* Screen rails are gated off in sleep; keep the SPI
			 * lines low so the unpowered panel is not back-
			 * powered through its ESD diodes (JDI requires
			 * interface lines at GND level while VDDI/VCI off). */
			low-power-enable;
			bias-pull-down;
		};
	};
};

/*
 * Dive Computer V2 rev 1 - nRF52833 QDAA (QFN40)
 *
 * Board hardware description, matching the KiCad schematic.
 * Power architecture: high-voltage mode (VDDH = battery on pin 9, VDD
 * pins decoupling only) - the internal REG0 LDO generates the 1.8 V
 * digital supply (REGOUT0 default), so all GPIO levels are 1.8 V.
 *
 * SPDX-License-Identifier: Apache-2.0
 */

/dts-v1/;
#include <nordic/nrf52833_qdaa.dtsi>
#include "dc_v2_1_nrf52833-pinctrl.dtsi"

/ {
	model = "Dive Computer V2 rev 1";
	compatible = "dive,dc-v2-1";

	chosen {
		zephyr,sram = &sram0;
		zephyr,flash = &flash0;
		zephyr,code-partition = &slot0_partition;
		/* No UART is routed on this board (no spare QFN40 GPIO);
		 * use SEGGER RTT over SWD for console output. */
	};

	/* GPIO pin assignments (gpio-leds/gpio-keys, sensor and screen
	 * control pins, SPI chip select) live in app.overlay so they are
	 * visible and editable in the Devicetree Visual Editor. */
};

/* GPIO ports and GPIOTE are disabled by default in the SoC dtsi;
 * enable them explicitly like the Nordic reference boards do. */
&gpiote {
	status = "okay";
};

&gpio0 {
	status = "okay";
};

&gpio1 {
	status = "okay";
};

/* P0.18/nRESET is wired to the debug connector: configure it as
 * hardware reset so a locked/sleeping device can always be
 * re-attached (same effect as nrfjprog --pinresetenable). */
&uicr {
	gpio-as-nreset;
};

&i2c0 {
	status = "okay";
	pinctrl-0 = <&i2c0_default>;
	pinctrl-1 = <&i2c0_sleep>;
	pinctrl-names = "default", "sleep";
	clock-frequency = <400000>;

	/* Magnetometer, I2C mode (CS pin tied high), fixed address.
	 * INT/DRDY not routed to the MCU: polled. */
	lis2mdl@1e {
		compatible = "st,lis2mdl";
		reg = <0x1e>;
	};

	/* Accelerometer, I2C mode (CS high), SA0 high. INT1 routed
	 * (wake-on-motion, assigned in app.overlay); INT2 not routed
	 * per pin budget decision. */
	acc: lis2dux12@19 {
		compatible = "st,lis2dux12";
		reg = <0x19>;
	};

	/* Pressure sensor, fixed address. */
	ms5837: ms5837@76 {
		compatible = "meas,ms5837-30ba";
		reg = <0x76>;
	};

